'use client';

import { useEffect, useState } from 'react';
import { toast } from 'sonner';
import type { FileManagerProps, FileItem, ViewMode } from './lib/types';
import { FileManagerHeader } from './file-manager-header';
import { FileManagerContent } from './file-manager-content';
import { SelectedFilesPreview } from './selected-files-preview';
import { FileManagerFooter } from './file-manager-footer';
import { ImageCropper } from './image-cropper';
import { NewFolderDialog, DeleteDialog, PreviewDialog } from './dialogs';
import { Sidebar, SidebarContent, SidebarProvider } from './components/ui/sidebar';
import { createFileFromCrop, downloadFile, deleteFileItem, renameFileItem } from './lib/file-operations';
import FileManagerTree from './file-manager-tree';
import { FileManagerBreadcrumb } from './file-manager-breadcrumb';
import { FileUploader } from './uploader/uploader';
import { useFiles } from './lib/use-files';
import { rootDir, getFileUrl } from './lib/utils';
import { useFileManagerContext } from './components/file-manager-provider';

export function FileManager({
  onSelect,
  onClose,
  multiple = true,

  selectButtonText = 'Add to Lesson',
}: FileManagerProps) {
  // State management
  const [selectedFiles, setSelectedFiles] = useState<FileItem[]>([]);
  const [pwd, setPwd] = useState<FileItem[]>([rootDir]);
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const pwdID = pwd[pwd.length - 1]?.id;

  // Files
  const { config, apiClient } = useFileManagerContext();
  const res = useFiles();

  // Dialog states
  const [showNewFolderDialog, setShowNewFolderDialog] = useState(false);
  const [showUploadDialog, setShowUploadDialog] = useState(false);
  const [showDeleteDialog, setShowDeleteDialog] = useState(false);
  const [showPreviewModal, setShowPreviewModal] = useState(false);
  const [showCropper, setShowCropper] = useState(false);

  // Form states
  const [fileToDelete, setFileToDelete] = useState<FileItem | null>(null);
  const [previewFile, setPreviewFile] = useState<FileItem | null>(null);
  const [imageToCrop, setImageToCrop] = useState<string>('');

  // File editing states
  const [editingFileId, setEditingFileId] = useState<string | null>(null);
  const [editingFileName, setEditingFileName] = useState('');

  // Navigation functions
  const navigateToFolder = (folder: FileItem) => {
    setPwd([...pwd, folder]);
    res.setPage(1);
  };

  // File selection
  const handleFileSelect = (file: FileItem) => {
    if (file.type === 'folder') {
      if (pwd[pwd.length - 1].id !== file.id) {
        navigateToFolder(file);
      }
      return;
    }

    if (multiple) {
      setSelectedFiles((prev) => {
        const isSelected = prev.some((f) => f.id === file.id);
        if (isSelected) {
          return prev.filter((f) => f.id !== file.id);
        } else {
          return [...prev, file];
        }
      });
    } else {
      setSelectedFiles([file]);
    }
  };

  // File operations
  const handleEditFile = (file: FileItem) => {
    setEditingFileId(file.id);
    setEditingFileName(file.name);
  };

  const handleSaveEdit = async () => {
    if (editingFileId && editingFileName.trim()) {
      const fileToRename = res.data?.find((f) => f.id === editingFileId);
      if (fileToRename) {
        try {
          await renameFileItem(apiClient, fileToRename, editingFileName.trim());
          res.mutate();
          toast.success('Item renamed successfully!');
        } catch (error) {
          toast.error('Failed to rename item');
          console.error(error);
        }
      }
      setEditingFileId(null);
      setEditingFileName('');
    }
  };

  const handleCancelEdit = () => {
    setEditingFileId(null);
    setEditingFileName('');
  };

  const handleDownloadFile = async (file: FileItem) => {
    await downloadFile(file);
    toast.success('File downloaded successfully!');
  };

  const handlePreviewFile = (file: FileItem) => {
    if (file.mime_type && (file.mime_type.startsWith('image/') || file.mime_type.startsWith('video/'))) {
      setPreviewFile(file);
      setShowPreviewModal(true);
    } else {
      toast.error('Preview is only available for image and video files');
    }
  };

  const handleDeleteFile = (file: FileItem) => {
    setFileToDelete(file);
    setShowDeleteDialog(true);
  };

  const confirmDeleteFile = async () => {
    if (fileToDelete) {
      try {
        await deleteFileItem(apiClient, fileToDelete);
        setSelectedFiles((prev) => prev.filter((f) => f.id !== fileToDelete.id));
        res.mutate();
        toast.success('Item deleted successfully!');
      } catch (error) {
        toast.error('Failed to delete item');
        console.error(error);
      }
      setFileToDelete(null);
      setShowDeleteDialog(false);
    }
  };

  // Image cropping
  const handleCropSave = (croppedImageUrl: string) => {
    const pathArray = pwd.map((dir) => dir.name).filter((name) => name !== 'Root');
    createFileFromCrop(croppedImageUrl, pathArray);
    setShowCropper(false);
    setImageToCrop('');
  };

  // biome-ignore lint/correctness/useExhaustiveDependencies: we want to re-run the effect when the pwdID changes
  useEffect(() => {
    res.setFilter('dir_id', pwdID);
    if (res.search) res.setSearch('');
  }, [pwdID]);

  return (
    <>
      {/* Main Content */}
      <>
        {/* Header */}
        <FileManagerHeader
          searchQuery={res.search}
          viewMode={viewMode}
          sortValue={res.sort}
          onSearchChange={res.setSearch}
          onViewModeChange={setViewMode}
          onSortChange={res.setSort}
          onUploadClick={() => setShowUploadDialog((val) => !val)}
          onNewFolderClick={() => setShowNewFolderDialog(true)}
          onReload={res.mutate}
        />

        {/* Content Area with Sidebar */}
        <SidebarProvider className='items-start min-h-full flex-1'>
          <Sidebar collapsible='none' className='hidden md:flex'>
            <SidebarContent>
              <div>
                <FileManagerTree />
                <div className='h-28'></div>
              </div>
            </SidebarContent>
          </Sidebar>

          {/* Main Content Area */}
          <div className='flex-1 px-4 overflow-y-auto space-y-2 max-h-full h-full'>
            {/* Current Path */}
            <FileManagerBreadcrumb pwd={pwd} setPwd={setPwd} />

            {showUploadDialog ? (
              <>
                <FileUploader
                  pwd={pwd[pwd.length - 1]}
                  onClose={() => {
                    setShowUploadDialog(false);
                    res.mutate();
                  }}
                />
              </>
            ) : (
              <FileManagerContent
                res={res}
                viewMode={viewMode}
                selectedFiles={selectedFiles}
                editingFileId={editingFileId}
                editingFileName={editingFileName}
                onFileSelect={handleFileSelect}
                onFileDoubleSelect={(file) => {
                  handleFileSelect(file);
                  onSelect(selectedFiles);
                  onClose();
                }}
                onEditFile={handleEditFile}
                onSaveEdit={handleSaveEdit}
                onCancelEdit={handleCancelEdit}
                onFileNameChange={setEditingFileName}
                onDownloadFile={handleDownloadFile}
                onPreviewFile={handlePreviewFile}
                onDeleteFile={handleDeleteFile}
              />
            )}
            <div className='h-28'></div>
          </div>
        </SidebarProvider>

        {/* Selected Files Preview */}
        <SelectedFilesPreview
          selectedFiles={selectedFiles}
          onRemoveFile={(fileId) => setSelectedFiles((prev) => prev.filter((f) => f.id !== fileId))}
          onClearAll={() => setSelectedFiles([])}
        />

        {/* Footer */}
        <FileManagerFooter
          totalFiles={res.pagination?.total || 0}
          selectedFilesCount={selectedFiles.length}
          selectButtonText={selectButtonText}
          onSelect={() => {
            onSelect(selectedFiles);
            onClose();
          }}
        />
      </>

      {/* Dialogs */}
      <NewFolderDialog
        pwdID={pwdID}
        isOpen={showNewFolderDialog}
        onClose={() => setShowNewFolderDialog(false)}
        onCreate={() => {
          setShowNewFolderDialog(false);
          res.mutate();
        }}
      />

      <DeleteDialog
        isOpen={showDeleteDialog}
        onClose={() => setShowDeleteDialog(false)}
        fileName={fileToDelete?.name || ''}
        onConfirm={confirmDeleteFile}
      />

      <PreviewDialog
        isOpen={showPreviewModal}
        onClose={() => setShowPreviewModal(false)}
        file={
          previewFile
            ? {
                id: previewFile.id,
                name: previewFile.name,
                url: getFileUrl(previewFile.id, config.assetBaseUrl),
                mimeType: previewFile.mime_type,
              }
            : null
        }
        onDownload={() => previewFile && handleDownloadFile(previewFile)}
      />

      <ImageCropper
        isOpen={showCropper}
        onClose={() => setShowCropper(false)}
        imageToCrop={imageToCrop}
        onSave={handleCropSave}
      />
    </>
  );
}
