import { UppyContext, useUppyState } from '@uppy/react';
import { useContext } from 'react';

export function useUploaderState() {
  const uppyCtxVal = useContext(UppyContext);
  const uppy = uppyCtxVal.uppy!;
  const state = useUppyState(uppy, (state) => ({
    allowNewUpload: state.allowNewUpload,
    canShowProgress: state.capabilities.uploadProgress,
    canPause: state.capabilities.resumableUploads,
    canCancel: state.capabilities.individualCancellation,
    isPaused: state.paused,
    isUploading: state.totalProgress > 0,
    progress: state.totalProgress,
    files: state.files,
    error: state.error,
    metaFields: state,
    state: state,
  }));

  const handleUpload = () => {
    uppy.upload();
  };

  const handlePauseResume = () => {
    if (state.isPaused) {
      uppy.resumeAll();
    } else {
      uppy.pauseAll();
    }
  };

  const handleCancel = () => {
    uppy.cancelAll();
  };

  return { state, handleUpload, handlePauseResume, handleCancel };
}
