"use client";

import React, { useState } from "react";
import { Upload } from "lucide-react";
import { Button } from "./components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogFooter,
  DialogTitle,
} from "./components/ui/dialog";
import { Input } from "./components/ui/input";
import { Label } from "./components/ui/label";
import { createFolder } from "./lib/file-operations";
import { useFileManagerContext } from "./components/file-manager-provider";
import { useApiAction } from "@softimist/api";

interface NewFolderDialogProps {
  pwdID: string;
  isOpen: boolean;
  onClose: () => void;
  onCreate: () => void;
}

export function NewFolderDialog({
  isOpen,
  onClose,
  onCreate,
  pwdID,
}: NewFolderDialogProps) {
  const [name, setName] = useState("");
  const { apiClient } = useFileManagerContext();

  const action = useApiAction({
    action: () => createFolder(apiClient, name, pwdID),
    showToast: true,
    onSuccess: () => {
      onCreate();
      setName("");
    },
  });
  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === "Enter") {
      action.execute();
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-md">
        <DialogTitle className="py-3">Create New Folder</DialogTitle>
        <div className="space-y-4">
          <div>
            <Label htmlFor="folderName" className="py-3">
              Folder Name
            </Label>
            <Input
              id="folderName"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Enter folder name"
              onKeyDown={handleKeyPress}
            />
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={onClose}>
            Cancel
          </Button>
          <Button
            onClick={() => action.execute()}
            disabled={!name.trim() || action.isLoading}
          >
            {action.isLoading ? "Creating..." : "Create Folder"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

interface DeleteDialogProps {
  isOpen: boolean;
  onClose: () => void;
  fileName: string;
  onConfirm: () => void;
}

export function DeleteDialog({
  isOpen,
  onClose,
  fileName,
  onConfirm,
}: DeleteDialogProps) {
  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-md">
        <DialogTitle>Delete File</DialogTitle>
        <div className="space-y-4">
          <p className="text-gray-600">
            Are you sure you want to delete &quot;{fileName}&quot;? This action
            cannot be undone.
          </p>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={onClose}>
            Cancel
          </Button>
          <Button variant="destructive" onClick={onConfirm}>
            Delete
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

interface PreviewDialogProps {
  isOpen: boolean;
  onClose: () => void;
  file: { id: string; name: string; url: string; mimeType?: string } | null;
  onDownload: () => void;
}

export function PreviewDialog({
  isOpen,
  onClose,
  file,
  onDownload,
}: PreviewDialogProps) {
  const { components } = useFileManagerContext();
  const Image = components?.Image;
  const VideoPlayer = components?.VideoPlayer;
  const isVideo = file?.mimeType?.startsWith("video/");
  const isImage = file?.mimeType?.startsWith("image/");
  const fileUrl = file?.url;

  return (
    <Dialog open={isOpen} onOpenChange={onClose}>
      <DialogContent className="max-w-4xl max-h-[80vh]">
        <DialogTitle>{isVideo ? "Video Preview" : "Image Preview"}</DialogTitle>
        <div className="flex items-center justify-center p-4">
          {file && file.url && isImage && Image && (
            <Image
              src={file.url}
              alt={file.name}
              width={800}
              height={600}
              className="max-w-full w-auto max-h-[60vh] object-contain rounded"
            />
          )}
          {file && fileUrl && isVideo && VideoPlayer && (
            <div className="w-full aspect-video bg-black rounded overflow-hidden">
              <VideoPlayer id={file.id} src={fileUrl} title={file.name} />
            </div>
          )}
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={onClose}>
            Close
          </Button>
          {file && (
            <Button onClick={onDownload}>
              <Upload className="w-4 h-4 mr-2" />
              Download
            </Button>
          )}
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
