'use client';

import { Check } from 'lucide-react';
import { Badge } from './components/ui/badge';
import { TableCell } from './components/ui/table';
import { FileItem } from './lib/types';
import { formatFileSize } from './lib/utils';
import { FileIcon } from './file-icon';
import { FileActions } from './file-actions';
import { FileNameEditor } from './file-name-editor';

interface FileItemListProps {
  file: FileItem;
  isSelected: boolean;
  isEditing: boolean;
  editingFileName: string;
  onFileSelect: (file: FileItem) => void;
  onFileDoubleSelect: (file: FileItem) => void;
  onEditFile: (file: FileItem) => void;
  onSaveEdit: () => void;
  onCancelEdit: () => void;
  onFileNameChange: (name: string) => void;
  onDownloadFile: (file: FileItem) => void;
  onPreviewFile: (file: FileItem) => void;
  onDeleteFile: (file: FileItem) => void;
}

export function FileItemList({
  file,
  isSelected,
  isEditing,
  editingFileName,
  onFileSelect,
  onFileDoubleSelect,
  onEditFile,
  onSaveEdit,
  onCancelEdit,
  onFileNameChange,
  onDownloadFile,
  onPreviewFile,
  onDeleteFile,
}: FileItemListProps) {
  const handleClick = () => {
    onFileSelect(file);
  };

  const handleDoubleClick = () => {
    onFileDoubleSelect(file);
  };

  return (
    <>
      {/* Icon */}
      <TableCell
        className={`w-8 shrink-0 flex items-center justify-center cursor-pointer hover:bg-accent transition-colors ${
          isSelected ? 'bg-accent' : ''
        }`}
        onClick={handleClick}
        onDoubleClick={handleDoubleClick}
      >
        <FileIcon file={file} />
      </TableCell>

      {/* Name */}
      <TableCell
        className={`flex-1 truncate max-w-lg cursor-pointer hover:bg-accent transition-colors ${isSelected ? 'bg-accent' : ''}`}
        onClick={handleClick}
        onDoubleClick={handleDoubleClick}
        title={file.name}
      >
        {isEditing ? (
          <FileNameEditor
            fileName={editingFileName}
            viewMode='list'
            onFileNameChange={onFileNameChange}
            onSave={onSaveEdit}
            onCancel={onCancelEdit}
          />
        ) : (
          <span className='truncate'>{file.name || "'Untitled'"}</span>
        )}
      </TableCell>

      {/* Size */}
      <TableCell
        className={`w-24 text-right text-xs text-muted-foreground cursor-pointer hover:bg-accent transition-colors ${
          isSelected ? 'bg-accent' : ''
        }`}
        onClick={handleClick}
        onDoubleClick={handleDoubleClick}
      >
        {file.type === 'file' && file.size ? formatFileSize(file.size) : '-'}
      </TableCell>

      {/* Type */}
      <TableCell
        className={`w-24 text-right cursor-pointer hover:bg-accent transition-colors ${isSelected ? 'bg-accent' : ''}`}
        onClick={handleClick}
        onDoubleClick={handleDoubleClick}
      >
        <Badge variant='secondary' className='text-xs'>
          {file.mime_type || file.type}
        </Badge>
      </TableCell>

      {/* Actions */}
      <TableCell
        className={`w-20 flex justify-end gap-1 cursor-pointer hover:bg-accent transition-colors ${
          isSelected ? 'bg-accent' : ''
        }`}
        onClick={handleClick}
        onDoubleClick={handleDoubleClick}
      >
        {isSelected && <Check className='h-4 w-4 text-primary' />}
        <FileActions
          file={file}
          viewMode='list'
          onDownload={onDownloadFile}
          onPreview={onPreviewFile}
          onEdit={onEditFile}
          onDelete={onDeleteFile}
        />
      </TableCell>
    </>
  );
}
