'use client';

import { useState } from 'react';
import { asyncDataLoaderFeature, hotkeysCoreFeature, selectionFeature } from '@headless-tree/core';
import { useTree } from '@headless-tree/react';
import { FileIcon, FolderIcon, FolderOpenIcon } from 'lucide-react';
import { useFileManagerContext } from './components/file-manager-provider';
import { FileItem } from './lib/types';
import { getFileItems } from './lib/use-files';
import { Tree, TreeItem, TreeItemLabel } from './components/ui/tree';

const indent = 20;

type Item = FileItem & {
  children?: Item[];
};

export default function FileManagerTree() {
  const { apiClient, config } = useFileManagerContext();
  const [loadingItemData, setLoadingItemData] = useState<string[]>([]);
  const [loadingItemChildrens, setLoadingItemChildrens] = useState<string[]>([]);

  const tree = useTree<Item>({
    state: { loadingItemData, loadingItemChildrens },
    setLoadingItemData,
    setLoadingItemChildrens,
    initialState: {
      expandedItems: [''],
      selectedItems: [],
    },
    indent,
    rootItemId: '',
    getItemName: (item) => {
      return item.getItemData()?.name || "'Untitled'";
    },
    isItemFolder: (item) => item.getItemData()?.type === 'folder',
    dataLoader: {
      getItem: async (itemId): Promise<Item> => {
        const items = await getFileItems(apiClient, config.assetBaseUrl, itemId);
        return items[0];
      },
      getChildrenWithData: async (itemId): Promise<{ id: string; data: Item }[]> => {
        const items = await getFileItems(apiClient, config.assetBaseUrl, itemId);
        return items.map((item) => ({ id: item.id, data: item }));
      },
    },
    features: [asyncDataLoaderFeature, selectionFeature, hotkeysCoreFeature],
  });

  return (
    <Tree
      className='relative before:absolute before:inset-0 before:-ms-1 before:bg-[repeating-linear-gradient(to_right,transparent_0,transparent_calc(var(--tree-indent)-1px),var(--border)_calc(var(--tree-indent)-1px),var(--border)_calc(var(--tree-indent)))]'
      indent={indent}
      tree={tree}
    >
      {tree.getItems().map((item) => {
        return (
          <TreeItem key={item.getId()} item={item}>
            <TreeItemLabel className='before:bg-background relative before:absolute before:inset-x-0 before:-inset-y-0.5 before:-z-10'>
              <span className='flex items-center gap-2'>
                {item.isFolder() ? (
                  item.isExpanded() ? (
                    <FolderOpenIcon className='text-muted-foreground pointer-events-none size-4' />
                  ) : (
                    <FolderIcon className='text-muted-foreground pointer-events-none size-4' />
                  )
                ) : (
                  <FileIcon className='text-muted-foreground pointer-events-none size-4' />
                )}
                <span className='line-clamp-1 flex-1 text-left'>{item.getItemName()}</span>
              </span>
            </TreeItemLabel>
          </TreeItem>
        );
      })}
    </Tree>
  );
}
