import { FileItem } from './types';
import { generateUniqueId } from './utils';
import type { HttpClient } from '@softimist/api';

export function createFolder(apiClient: HttpClient, name: string, pwdID?: string) {
  const body = pwdID ? { name, parent_id: pwdID } : { name };
  return apiClient.post('/api/v1/files', body);
}

export function createFileFromCrop(croppedImageUrl: string, currentPath: string[]): FileItem {
  const uniqueId = generateUniqueId();

  return {
    id: uniqueId,
    name: `cropped-${Date.now()}.jpg`,
    type: 'file',
    size: 0, // Will be calculated
    mime_type: 'image/jpeg',
    url: croppedImageUrl,
    path: currentPath.join('__SLASH__'),
    created_at: new Date().toISOString(),
  };
}

export function renameFileItem(apiClient: HttpClient, fileItem: FileItem, newName: string) {
  return apiClient.patch('/api/v1/files/' + fileItem.id, {
    name: newName,
  });
}

export function deleteFileItem(apiClient: HttpClient, fileItem: FileItem) {
  return apiClient.delete('/api/v1/files/' + fileItem.id);
}

export async function downloadFile(file: FileItem): Promise<void> {
  if (!file.url) {
    console.error('No URL available for download');
    return;
  }

  const link = document.createElement('a');
  link.href = file.url;
  link.download = file.name;
  link.target = '_blank';
  document.body.appendChild(link);
  link.click();
  document.body.removeChild(link);
}
