export type FileItem = {
  id: string;
  name: string;
  path: string;
  type: 'file' | 'folder';
  size?: number;
  size_in_bytes?: number;
  url?: string;
  bucket_key?: string;
  mime_type?: string;
  created_at: string;
};

export interface FileManagerProps {
  onSelect: (files: FileItem[]) => void;
  onClose: () => void;
  multiple?: boolean;
  acceptedTypes?: string[];
  maxSize?: number; // in MB
  selectButtonText?: string; // Custom text for select button
}

export interface TreeNode {
  id: string;
  name: string;
  type: 'file' | 'folder';
  children: TreeNode[];
  level: number;
  parentId?: string;
  isExpanded?: boolean;
  fileData: FileItem;
}

export interface FileTreeSidebarProps {
  files: FileItem[];
  currentPath: string[];
  onNavigate: (path: string[]) => void;
  onFolderClick: (folderId: string) => void;
  className?: string;
  selectedItem?: string | null;
  onSelectItem?: (id: string) => void;
}

export type ViewMode = 'list' | 'grid';

export type AspectRatio = 'rectangle' | 'square' | 'wide' | 'photo' | 'portrait' | 'ultrawide' | 'story' | 'custom';

export const aspectRatios: Record<AspectRatio, number | undefined> = {
  rectangle: 4 / 3,
  square: 1,
  wide: 5 / 3,
  photo: 3 / 2,
  portrait: 2 / 3,
  ultrawide: 21 / 9,
  story: 9 / 16,
  custom: undefined,
};
