'use client';

import { File } from 'lucide-react';
import { Button } from './components/ui/button';
import { Card, CardContent } from './components/ui/card';
import { Badge } from './components/ui/badge';
import { FileItem } from './lib/types';
import { formatFileSize } from './lib/utils';
import { useFileManagerContext } from './components/file-manager-provider';

interface SelectedFilesPreviewProps {
  selectedFiles: FileItem[];
  onRemoveFile: (fileId: string) => void;
  onClearAll: () => void;
}

export function SelectedFilesPreview({ selectedFiles, onRemoveFile, onClearAll }: SelectedFilesPreviewProps) {
  const { components } = useFileManagerContext();
  const Image = components?.Image;
  
  if (selectedFiles.length === 0) return null;

  return (
    <div className='mt-3 p-2 rounded-lg'>
      <div className='flex items-center justify-between mb-2'>
        <div className='flex items-center space-x-2'>
          <div className='w-2 h-2 bg-blue-500 rounded-full'></div>
          <h3 className='text-sm font-semibold text-gray-900'>Selected Files</h3>
          <Badge variant='secondary' className='text-xs font-medium'>
            {selectedFiles.length} {selectedFiles.length === 1 ? 'file' : 'files'}
          </Badge>
        </div>
        <Button
          variant='ghost'
          size='sm'
          onClick={onClearAll}
          className='text-xs text-gray-500 hover:text-gray-700 hover:bg-white/50'
        >
          Clear All
        </Button>
      </div>

      <div className='grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 xl:grid-cols-6 gap-1.5'>
        {selectedFiles.map((file) => (
          <Card
            key={file.id}
            className='p-1.5 border border-gray-200 shadow-sm hover:shadow-md transition-all duration-200'
          >
            <CardContent className='p-0'>
              <div className='flex items-center gap-2 space-x-1.5'>
                <div className='flex-shrink-0'>
                  {file.mime_type && file.mime_type.startsWith('image/') && file.url && Image ? (
                    <div className='size-8 rounded-sm overflow-hidden border border-gray-200 bg-gray-50'>
                      <Image
                        src={file.url}
                        alt={file.name}
                        width={24}
                        height={24}
                        className='w-full h-full object-cover'
                      />
                    </div>
                  ) : (
                    <div className='size-8 rounded-sm bg-gray-100 border border-gray-200 flex items-center justify-center'>
                      <File className='size-4 text-gray-500' />
                    </div>
                  )}
                </div>

                <div className='flex-1 min-w-0'>
                  <div className='flex items-center justify-between'>
                    <div className='flex-1 min-w-0'>
                      <p className='text-[10px] font-medium text-gray-900 truncate' title={file.name}>
                        {file.name}
                      </p>
                      <div className='flex items-center space-x-1 mt-0.5'>
                        <Badge variant='outline' className='text-[8px] px-1 py-0'>
                          {file.type}
                        </Badge>
                        {file.size && <span className='text-[8px] text-gray-500'>{formatFileSize(file.size)}</span>}
                      </div>
                    </div>

                    <Button
                      variant='ghost'
                      size='icon'
                      className='h-4 w-4 text-gray-400 hover:text-red-500 hover:bg-red-50 ml-0.5'
                      onClick={() => onRemoveFile(file.id)}
                    >
                      <svg className='w-2 h-2' fill='none' stroke='currentColor' viewBox='0 0 24 24'>
                        <path strokeLinecap='round' strokeLinejoin='round' strokeWidth={2} d='M6 18L18 6M6 6l12 12' />
                      </svg>
                    </Button>
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}
