'use client';

import Uppy from '@uppy/core';
import { FilesList, UppyContextProvider } from '@uppy/react';
import UppyRemoteSources from '@uppy/remote-sources';
import UppyScreenCapture from '@uppy/screen-capture';
import UppyWebcam from '@uppy/webcam';
import XHR from '@uppy/xhr-upload';

import { useRef, useState } from 'react';
import { CustomDropzone } from './sources/custom-dropzone';
import { RemoteSource } from './sources/remote-source';
import { ScreenCapture } from './sources/screen-capture';
import { Webcam } from './sources/webcam';

import '@uppy/react/css/style.css';
import { UploadControls } from './upload-controls';
import { Button } from '../components/ui/button';
import { X } from 'lucide-react';
import { FileItem } from '../lib/types';
import { toast } from 'sonner';
import { useFileManagerContext } from '../components/file-manager-provider';

type Props = {
  pwd?: FileItem;
  onClose: () => void;
};

export function FileUploader({ pwd, onClose }: Props) {
  const dialogRef = useRef<HTMLDialogElement>(null);
  const [modalPlugin, setModalPlugin] = useState<'webcam' | 'dropbox' | 'screen-capture' | null>(null);

  function openModal(plugin: 'webcam' | 'dropbox' | 'screen-capture') {
    setModalPlugin(plugin);
    dialogRef.current?.showModal();
  }

  function closeModal() {
    setModalPlugin(null);
    dialogRef.current?.close();
  }

  return (
    <FileUploaderContext pwd={pwd}>
      <>
        <dialog ref={dialogRef} className='backdrop:bg-gray-500/50 rounded-lg shadow-xl p-0 fixed inset-0 m-auto'>
          {(() => {
            switch (modalPlugin) {
              case 'webcam':
                return <Webcam close={() => closeModal()} />;
              case 'dropbox':
                return <RemoteSource id='Dropbox' close={() => closeModal()} />;
              case 'screen-capture':
                return <ScreenCapture close={() => closeModal()} />;
              default:
                return null;
            }
          })()}
        </dialog>
        <div className='flex justify-between items-center'>
          <span className='font-semibold'>Upload Files</span>
          <Button variant='ghost' onClick={onClose}>
            <X className='size-4' />
            Close
          </Button>
        </div>
        <article className='text-sm'>
          <CustomDropzone openModal={(plugin) => openModal(plugin)} />
          <FilesList />
        </article>
        {/* <UploadButton /> */}
        <UploadControls onClose={onClose} />
        {/* <UploadProcessManager /> */}
      </>
    </FileUploaderContext>
  );
}

type UploaderContextProps = {
  pwd?: FileItem;
  children: React.ReactNode;
};

export function FileUploaderContext({ pwd, children }: UploaderContextProps) {
  const { config } = useFileManagerContext();
  const endpoint = pwd ? `${config.uploadEndpoint}?dir_id=${pwd.id}` : config.uploadEndpoint;
  const [uppy] = useState(() =>
    new Uppy()
      // .use(Tus, {
      //   endpoint: endpoint,
      // })
      .use(XHR, { endpoint: endpoint })
      // .use(AwsS3, {
      //   endpoint: endpoint,
      // })
      .use(UppyWebcam)
      .use(UppyScreenCapture)
      .use(UppyRemoteSources, { companionUrl: endpoint })
      .on('upload-error', (file, error, req) => {
        const r = req ? (req as XMLHttpRequest) : undefined;
        const res = r?.responseText ? JSON.parse(r?.responseText) : undefined;
        toast.error(file ? `Failed to upload "${file.name}"` : error.message, {
          description: res.message,
        });
      })
  );
  return <UppyContextProvider uppy={uppy}>{children}</UppyContextProvider>;
}
