'use client';

import { ImageUpIcon, Plus, Upload, X } from 'lucide-react';
import { useState } from 'react';
import { Dialog, DialogContent, DialogTrigger } from './components/ui/dialog';
import { FileManager } from './file-manager';
import { FileManagerProvider, type FileManagerComponents, type FileManagerConfig } from './components/file-manager-provider';
import { FileItem } from './lib/types';
import { Button } from './components/ui/button';
import { useFileManagerContext } from './components/file-manager-provider';
import type { HttpClient } from '@softimist/api';

type TriggerProps = {
  icon?: 'plus' | 'upload';
  value?: string;
  label?: string;
  placeholder?: string;
  disabled?: boolean;
  aspect?: number;
};

export interface FileManagerDialogProps {
  mode?: 'button' | 'dropzone';
  onSelect: (files: FileItem[]) => void;
  acceptedTypes?: string[];
  trigger?: TriggerProps;
  multiple?: boolean;
  // Provider props
  apiClient: HttpClient;
  components?: FileManagerComponents;
  config: FileManagerConfig;
}

function ButtonTrigger({ icon = 'plus', label = 'Select File' }: TriggerProps) {
  return (
    <Button variant='outline' asChild>
      <label>
        {icon === 'plus' ? <Plus /> : <Upload />} {label}
      </label>
    </Button>
  );
}

function DropzoneTrigger({
  value,
  label,
  placeholder,
  onRemove,
  aspect = 16 / 9,
}: TriggerProps & { onRemove: () => void }) {
  const { components } = useFileManagerContext();
  const Image = components?.Image;
  
  if (value) {
    return (
      <div className='relative border rounded-lg bg-transparent dark:bg-input/30' style={{ aspectRatio: aspect }}>
        {Image && <Image src={value} alt='Thumbnail' width={600} height={400} className='object-contain' />}
        <div className='absolute top-2 right-2'>
          <Button
            type='button'
            variant='outline'
            size='icon'
            className='rounded-full'
            onClick={(e) => {
              e.stopPropagation();
              onRemove();
            }}
            asChild
          >
            <X className='w-6 h-6 text-black' />
          </Button>
        </div>
      </div>
    );
  }
  return (
    <div
      className='border-2 border-dashed bg-transparent dark:bg-input/30 space-y-2 rounded-lg p-6 flex flex-col items-center justify-center px-4 py-3 text-center'
      style={{ aspectRatio: aspect }}
    >
      <div
        className='bg-background flex size-11 shrink-0 items-center justify-center rounded-full border'
        aria-hidden='true'
      >
        <ImageUpIcon className='size-6 opacity-60' />
      </div>
      {label && <p className='text-sm font-medium text-muted-foreground'>{label}</p>}
      {placeholder && <p className='text-xs text-muted-foreground'>{placeholder}</p>}
    </div>
  );
}

export function FileManagerDialog({ 
  mode = 'button', 
  trigger, 
  onSelect, 
  acceptedTypes, 
  multiple = false,
  apiClient,
  components,
  config,
}: FileManagerDialogProps) {
  const [showDialog, setShowDialog] = useState(false);
  
  return (
    <FileManagerProvider
      apiClient={apiClient}
      components={components}
      config={config}
    >
      <Dialog open={showDialog} onOpenChange={setShowDialog}>
        <DialogTrigger className={mode === 'dropzone' ? 'w-full' : ''} disabled={trigger?.disabled}>
          {mode === 'button' ? (
            <ButtonTrigger icon={trigger?.icon} label={trigger?.label} />
          ) : (
            <DropzoneTrigger
              value={trigger?.value}
              disabled={trigger?.disabled}
              label={trigger?.label}
              placeholder={trigger?.placeholder}
              aspect={trigger?.aspect}
              onRemove={() => onSelect([])}
            />
          )}
        </DialogTrigger>
        <DialogContent
          showCloseButton={false}
          className='sm:max-w-5xl w-[95vw] h-[95vh] max-h-[95vh] flex flex-col overflow-hidden p-0 gap-0'
        >
          <FileManager
            multiple={multiple}
            selectButtonText={trigger?.label}
            onSelect={(files) => {
              if (files.length > 0) {
                onSelect(files);
              }
              setShowDialog(false);
            }}
            onClose={() => setShowDialog(false)}
            acceptedTypes={acceptedTypes}
          />
        </DialogContent>
      </Dialog>
    </FileManagerProvider>
  );
}
