'use client';

import { Search, Upload, Plus, Grid3X3, List, X, RotateCw, ArrowUpDown, ArrowUp, ArrowDown } from 'lucide-react';
import { Button } from './components/ui/button';
import { Input } from './components/ui/input';
import type { ViewMode } from './lib/types';
import { DialogClose, DialogHeader, DialogTitle } from './components/ui/dialog';
import { Tabs, TabsList, TabsTrigger } from './components/ui/tabs';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from './components/ui/dropdown-menu';

type SortOption = {
  value: string;
  label: string;
};

const SORT_OPTIONS: SortOption[] = [
  { value: 'name:asc', label: 'Name (A-Z)' },
  { value: 'name:desc', label: 'Name (Z-A)' },
  { value: 'created_at:desc', label: 'Newest First' },
  { value: 'created_at:asc', label: 'Oldest First' },
  { value: 'size_in_bytes:desc', label: 'Largest First' },
  { value: 'size_in_bytes:asc', label: 'Smallest First' },
  { value: 'type:desc', label: 'Folders First' },
  { value: 'type:asc', label: 'Files First' },
];

interface FileManagerHeaderProps {
  searchQuery: string;
  viewMode: ViewMode;
  sortValue?: string;
  onSearchChange: (query: string) => void;
  onViewModeChange: (mode: ViewMode) => void;
  onSortChange?: (sort: string) => void;
  onUploadClick: () => void;
  onNewFolderClick: () => void;
  onReload?: () => void;
}

export function FileManagerHeader({
  searchQuery,
  viewMode,
  sortValue = '',
  onSearchChange,
  onViewModeChange,
  onSortChange,
  onUploadClick,
  onNewFolderClick,
  onReload,
}: FileManagerHeaderProps) {
  const currentSortLabel = SORT_OPTIONS.find((opt) => opt.value === sortValue)?.label || 'Default';

  return (
    <DialogHeader className='flex flex-row items-center justify-between px-4 bg-accent py-2 sticky top-0 z-30'>
      <DialogTitle className='text-lg font-bold'>File Manager</DialogTitle>
      <div className='flex items-center space-x-2'>
        {onReload && (
          <Button variant='outline' size='sm' onClick={onReload}>
            <RotateCw className='size-4' />
          </Button>
        )}
        <div className='relative'>
          <Search className='absolute left-3 top-1/2 transform -translate-y-1/2 text-muted-foreground size-4' />
          <Input
            placeholder='Search files or folders...'
            value={searchQuery}
            onChange={(e) => onSearchChange(e.target.value)}
            className='pl-8 h-8 bg-background '
          />
        </div>
        {onSortChange && (
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant='outline' size='sm' className='gap-1'>
                <ArrowUpDown className='size-4' />
                <span className='hidden sm:inline'>{currentSortLabel}</span>
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align='end' className='w-48'>
              <DropdownMenuLabel>Sort By</DropdownMenuLabel>
              <DropdownMenuSeparator />
              {SORT_OPTIONS.map((option) => (
                <DropdownMenuItem
                  key={option.value}
                  onClick={() => onSortChange(option.value)}
                  className={sortValue === option.value ? 'bg-accent' : ''}
                >
                  {option.label}
                  {sortValue === option.value && (
                    <span className='ml-auto'>
                      {option.value.includes(':asc') ? (
                        <ArrowUp className='size-3' />
                      ) : (
                        <ArrowDown className='size-3' />
                      )}
                    </span>
                  )}
                </DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>
        )}
        <Button variant='outline' size='sm' onClick={onUploadClick}>
          <Upload className='size-4' />
          Upload
        </Button>
        <Button variant='outline' size='sm' onClick={onNewFolderClick}>
          <Plus className='size-4' />
          Folder
        </Button>
        {/* View Mode Toggle */}
        <Tabs value={viewMode} onValueChange={(value) => onViewModeChange(value as ViewMode)}>
          <TabsList>
            <TabsTrigger value='grid'>
              <Grid3X3 className='size-3.5' />
              <span className='sr-only'>Grid View</span>
            </TabsTrigger>
            <TabsTrigger value='list'>
              <List className='size-3.5' />
              <span className='sr-only'>List View</span>
            </TabsTrigger>
          </TabsList>
        </Tabs>
        <DialogClose asChild>
          <Button variant='outline' size='sm'>
            <X className='size-4' />
          </Button>
        </DialogClose>
      </div>
    </DialogHeader>
  );
}
