import { FileItem } from './types';
import { usePaginatedApi, type HttpClient, type ServerResponse, type UsePaginatedApiReturn } from '@softimist/api';
import { useFileManagerContext } from '../components/file-manager-provider';
import { getFileUrl } from './utils';

type ResBaseItem = {
  id: string;
  name: string;
  item_type: 'folder' | 'file';
  created_at: string;
};

type ResFile = ResBaseItem & {
  size_in_bytes: number;
  mime_type: string;
  bucket_key: string;
  created_at: string;
};

export function useFiles(dirID?: string): UsePaginatedApiReturn<FileItem> {
  const { apiClient, config } = useFileManagerContext();
  const path = '/api/v1/files';
  const options = dirID ? { persist: false, params: { dir_id: dirID } } : { persist: false };
  const { data, ...rest } = usePaginatedApi<ResBaseItem>(apiClient, path, options);
  const items: FileItem[] = data?.map((item) => mapItem(item, config.assetBaseUrl)) || [];

  return {
    ...rest,
    data: items,
  };
}

// Note: getFileItems is not a hook, so it can't use context directly
// It should only be called from within components that have access to context
// For now, we'll make it require the dependencies to be passed
export async function getFileItems(
  apiClient: HttpClient,
  assetBaseUrl: string,
  dirID?: string
): Promise<FileItem[]> {
  const path = '/api/v1/files';
  const params = dirID ? { dir_id: dirID } : {};
  const res = await apiClient.get<ServerResponse<ResBaseItem[]>>(path, { params });
  return res.data.map((item) => mapItem(item, assetBaseUrl));
}

function mapItem(item: ResBaseItem, assetBaseUrl: string): FileItem {
  if (item.item_type === 'folder') {
    const dir = item as ResBaseItem;
    return {
      id: dir.id,
      name: dir.name,
      type: 'folder',
      path: dir.id,
      created_at: dir.created_at,
    };
  }
  const file = item as ResFile;
  return getFileItemFromResponse(file, assetBaseUrl);
}

export function getFileItemFromResponse(file: ResFile, assetBaseUrl: string): FileItem {
  return {
    id: file.id,
    name: file.name,
    type: 'file',
    path: file.id,
    size: file.size_in_bytes,
    mime_type: file.mime_type,
    url: getFileUrl(file.id, assetBaseUrl),
    created_at: file.created_at,
  };
}
