'use client';

import { Check, File } from 'lucide-react';
import { Button } from './components/ui/button';
import { DialogClose, DialogFooter } from './components/ui/dialog';

interface FileManagerFooterProps {
  totalFiles: number;
  selectedFilesCount: number;
  selectButtonText: string;
  onSelect: () => void;
}

export function FileManagerFooter({
  totalFiles,
  selectedFilesCount,
  selectButtonText,
  onSelect,
}: FileManagerFooterProps) {
  return (
    <DialogFooter className='sticky bottom-0 z-20 px-4 py-2 bg-accent'>
      <div className='flex items-center space-x-4'>
        <div className='inline-flex items-center text-sm text-muted-foreground'>
          <File className='w-4 h-4 mr-2' />
          <span>{totalFiles} total files</span>
        </div>
        {selectedFilesCount > 0 && (
          <div className='inline-flex items-center text-sm text-primary'>
            <Check className='w-4 h-4 mr-2' />
            <span>{selectedFilesCount} selected</span>
          </div>
        )}
      </div>

      <div className='flex gap-2'>
        <DialogClose asChild>
          <Button variant='outline'>Cancel</Button>
        </DialogClose>
        <Button onClick={onSelect} disabled={selectedFilesCount === 0}>
          {selectButtonText} {selectedFilesCount > 0 && `(${selectedFilesCount})`}
        </Button>
      </div>
    </DialogFooter>
  );
}
