'use client';

import { Card } from './components/ui/card';
import { Table, TableBody, TableHead, TableHeader, TableRow } from './components/ui/table';
import { FileItem as FileItemType, ViewMode } from './lib/types';
import { FileItemList } from './file-item-list';
import { FileItemGrid } from './file-item-grid';
import type { UsePaginatedApiReturn } from '@softimist/api';
import { FileManagerPagination } from './file-manager-pagination';
import { FileManagerEmptyState } from './file-manager-empty-state';

interface FileManagerContentProps {
  res: UsePaginatedApiReturn<FileItemType>;
  viewMode: ViewMode;
  selectedFiles: FileItemType[];
  editingFileId: string | null;
  editingFileName: string;
  onFileSelect: (file: FileItemType) => void;
  onFileDoubleSelect: (file: FileItemType) => void;
  onEditFile: (file: FileItemType) => void;
  onSaveEdit: () => void;
  onCancelEdit: () => void;
  onFileNameChange: (name: string) => void;
  onDownloadFile: (file: FileItemType) => void;
  onPreviewFile: (file: FileItemType) => void;
  onDeleteFile: (file: FileItemType) => void;
}

export function FileManagerContent({
  res,
  viewMode,
  selectedFiles,
  editingFileId,
  editingFileName,
  onFileSelect,
  onFileDoubleSelect,
  onEditFile,
  onSaveEdit,
  onCancelEdit,
  onFileNameChange,
  onDownloadFile,
  onPreviewFile,
  onDeleteFile,
}: FileManagerContentProps) {
  if (res.data.length === 0) {
    return <FileManagerEmptyState />;
  }

  if (viewMode === 'list') {
    return (
      <Card className='pt-0 gap-2'>
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead className='w-8'></TableHead>
              <TableHead>Name</TableHead>
              <TableHead className='w-24 text-right'>Size</TableHead>
              <TableHead className='w-24 text-right'>Type</TableHead>
              <TableHead className='w-20 text-right'>Actions</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {res.data.map((file) => (
              <TableRow key={file.id}>
                <FileItemList
                  file={file}
                  isSelected={selectedFiles.some((f) => f.id === file.id)}
                  isEditing={editingFileId === file.id}
                  editingFileName={editingFileName}
                  onFileSelect={onFileSelect}
                  onFileDoubleSelect={onFileDoubleSelect}
                  onEditFile={onEditFile}
                  onSaveEdit={onSaveEdit}
                  onCancelEdit={onCancelEdit}
                  onFileNameChange={onFileNameChange}
                  onDownloadFile={onDownloadFile}
                  onPreviewFile={onPreviewFile}
                  onDeleteFile={onDeleteFile}
                />
              </TableRow>
            ))}
          </TableBody>
        </Table>
        <FileManagerPagination res={res} />
      </Card>
    );
  }

  // Grid view
  return (
    <>
      <div className='grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3 pb-1'>
        {res.data.map((file) => (
          <FileItemGrid
            key={file.id}
            file={file}
            isSelected={selectedFiles.some((f) => f.id === file.id)}
            isEditing={editingFileId === file.id}
            editingFileName={editingFileName}
            onFileSelect={onFileSelect}
            onEditFile={onEditFile}
            onSaveEdit={onSaveEdit}
            onCancelEdit={onCancelEdit}
            onFileNameChange={onFileNameChange}
            onDownloadFile={onDownloadFile}
            onPreviewFile={onPreviewFile}
            onDeleteFile={onDeleteFile}
          />
        ))}
      </div>
      <FileManagerPagination res={res} />
    </>
  );
}
