import { Button } from '../../components/ui/button';
import { X } from 'lucide-react';

type ButtonProps = {
  type: 'button';
  onClick: () => void;
  disabled: boolean;
};

interface ErrorDisplayProps {
  error: Error | null;
}

function ErrorDisplay({ error }: ErrorDisplayProps) {
  if (!error) return null;

  const errorMessage = error.message ? `Camera error: ${error.message}` : 'An unknown camera error occurred.';

  return (
    <div className='p-4 my-2 text-red-700 bg-red-100 border border-red-400 rounded'>
      <p className='font-bold'>Error</p>
      <p>{errorMessage}</p>
    </div>
  );
}

export interface MediaCaptureProps {
  title: string;
  close: () => void;
  getVideoProps: () => Record<string, unknown>;
  getPrimaryActionButtonProps: () => ButtonProps;
  primaryActionButtonLabel: string;
  mediaError: Error | null;
  getRecordButtonProps: () => ButtonProps;
  getStopRecordingButtonProps: () => ButtonProps;
  getSubmitButtonProps: () => ButtonProps;
  getDiscardButtonProps: () => ButtonProps;
}

export function MediaCapture({
  title,
  close,
  getVideoProps,
  getPrimaryActionButtonProps,
  primaryActionButtonLabel,
  getRecordButtonProps,
  mediaError,
  getStopRecordingButtonProps,
  getSubmitButtonProps,
  getDiscardButtonProps,
}: MediaCaptureProps) {
  return (
    <div className='p-4 max-w-lg w-full'>
      <div className='flex justify-between items-center mb-4'>
        <h2 className='text-xl font-bold'>{title}</h2>
        <Button type='button' onClick={close} variant='ghost' size='icon'>
          <X className='size-4' />
        </Button>
      </div>
      <ErrorDisplay error={mediaError} />
      <video className='border-2 w-full rounded-lg data-[uppy-mirrored=true]:scale-x-[-1]' {...getVideoProps()}>
        <track kind='captions' />
      </video>
      <div className='flex gap-4 flex-wrap mt-4'>
        <Button variant='default' {...getPrimaryActionButtonProps()}>
          {primaryActionButtonLabel}
        </Button>
        <Button variant='default' {...getRecordButtonProps()}>
          Record
        </Button>
        <Button variant='destructive' {...getStopRecordingButtonProps()}>
          Stop
        </Button>
        <Button variant='default' {...getSubmitButtonProps()}>
          Submit
        </Button>
        <Button variant='outline' {...getDiscardButtonProps()}>
          Discard
        </Button>
      </div>
    </div>
  );
}
