'use client';

import React from 'react';
import { Button } from './components/ui/button';
import { Input } from './components/ui/input';

interface FileNameEditorProps {
  fileName: string;
  viewMode: 'list' | 'grid';
  onFileNameChange: (name: string) => void;
  onSave: () => void;
  onCancel: () => void;
}

export function FileNameEditor({ fileName, viewMode, onFileNameChange, onSave, onCancel }: FileNameEditorProps) {
  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      onSave();
    } else if (e.key === 'Escape') {
      onCancel();
    }
  };

  if (viewMode === 'list') {
    return (
      <div className='flex items-center space-x-2'>
        <Input
          value={fileName}
          onChange={(e) => onFileNameChange(e.target.value)}
          onKeyPress={handleKeyPress}
          className='h-6 text-sm'
          autoFocus
        />
        <Button size='sm' variant='ghost' onClick={onSave} className='h-6 px-2'>
          ✓
        </Button>
        <Button size='sm' variant='ghost' onClick={onCancel} className='h-6 px-2 text-red-500'>
          ✕
        </Button>
      </div>
    );
  }

  // Grid view
  return (
    <div className='space-y-1'>
      <Input
        value={fileName}
        onChange={(e) => onFileNameChange(e.target.value)}
        onKeyPress={handleKeyPress}
        className='h-6 text-xs text-center'
        autoFocus
      />
      <div className='flex justify-center space-x-1'>
        <Button size='sm' variant='ghost' onClick={onSave} className='h-4 px-1 text-xs'>
          ✓
        </Button>
        <Button size='sm' variant='ghost' onClick={onCancel} className='h-4 px-1 text-xs text-red-500'>
          ✕
        </Button>
      </div>
    </div>
  );
}
