'use client';

import { Folder, File } from 'lucide-react';
import { FileItem } from './lib/types';
import { getFileIcon } from './lib/utils';
import { useFileManagerContext } from './components/file-manager-provider';

interface FileIconProps {
  file: FileItem;
  className?: string;
}

export function FileIcon({ file, className = 'w-5 h-5' }: FileIconProps) {
  const { components } = useFileManagerContext();
  const Image = components?.Image;
  const iconType = getFileIcon(file);

  if (iconType === 'folder') {
    return <Folder className={`${className} text-primary`} />;
  }

  if (iconType === 'image' && file.url && Image) {
    return (
      <Image src={file.url} alt={file.name} width={20} height={20} className={`${className} object-cover rounded`} />
    );
  }

  return <File className={`${className} text-muted-foreground`} />;
}
