import { centerCrop, makeAspectCrop } from 'react-image-crop';
import { FileItem } from './types';
import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export const rootDir: FileItem = {
  id: '',
  name: 'Root',
  path: '',
  type: 'folder',
  created_at: new Date().toISOString(),
};

// Helper function to center the crop with better initial size
export function centerAspectCrop(mediaWidth: number, mediaHeight: number, aspect: number) {
  return centerCrop(
    makeAspectCrop(
      {
        unit: '%',
        width: 90,
        height: 90,
      },
      aspect,
      mediaWidth,
      mediaHeight
    ),
    mediaWidth,
    mediaHeight
  );
}

export const formatFileSize = (bytes: number): string => {
  if (bytes === 0) return '0 Bytes';
  const k = 1024;
  const sizes = ['Bytes', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(k));
  return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
};

export const getFileIcon = (file: FileItem) => {
  if (file.type === 'folder') {
    return 'folder';
  }
  if (file.mime_type && file.mime_type.startsWith('image/') && file.url) {
    return 'image';
  }
  return 'file';
};

export const generateUniqueId = (): string => {
  return `file-${Date.now()}-${Math.random().toString(36).substr(2, 9)}-${Math.random().toString(36).substr(2, 9)}`;
};

export function getFileUrl(fileId: string, assetBaseUrl?: string) {
  return `${assetBaseUrl || ''}/api/v1/files/preview-id/${fileId}`;
}
