'use client';

import { Check } from 'lucide-react';
import { Card, CardContent } from './components/ui/card';
import { FileItem } from './lib/types';
import { formatFileSize } from './lib/utils';
import { FileIcon } from './file-icon';
import { FileActions } from './file-actions';
import { FileNameEditor } from './file-name-editor';

interface FileItemGridProps {
  file: FileItem;
  isSelected: boolean;
  isEditing: boolean;
  editingFileName: string;
  onFileSelect: (file: FileItem) => void;
  onEditFile: (file: FileItem) => void;
  onSaveEdit: () => void;
  onCancelEdit: () => void;
  onFileNameChange: (name: string) => void;
  onDownloadFile: (file: FileItem) => void;
  onPreviewFile: (file: FileItem) => void;
  onDeleteFile: (file: FileItem) => void;
}

export function FileItemGrid({
  file,
  isSelected,
  isEditing,
  editingFileName,
  onFileSelect,
  onEditFile,
  onSaveEdit,
  onCancelEdit,
  onFileNameChange,
  onDownloadFile,
  onPreviewFile,
  onDeleteFile,
}: FileItemGridProps) {
  const handleClick = () => {
    onFileSelect(file);
  };

  return (
    <Card
      className={`relative group cursor-pointer transition-all duration-200 h-[110px] w-full ${
        isSelected ? 'ring-2 ring-primary' : 'hover:ring-1 hover:ring-border'
      }`}
      onClick={handleClick}
    >
      <CardContent className='p-2 h-full'>
        <div className='flex flex-col items-center justify-center w-full h-full'>
          {/* Icon */}
          <div className='flex-1 flex items-center justify-center min-h-[60px]'>
            <FileIcon file={file} className='w-8 h-8' />
          </div>

          {/* Name and Size */}
          <div className='flex-shrink-0 text-center w-full'>
            <div className='w-full max-w-[120px] mx-auto'>
              {isEditing ? (
                <FileNameEditor
                  fileName={editingFileName}
                  viewMode='grid'
                  onFileNameChange={onFileNameChange}
                  onSave={onSaveEdit}
                  onCancel={onCancelEdit}
                />
              ) : (
                <>
                  <div className='text-xs font-medium text-foreground truncate' title={file.name}>
                    {file.name || "'Untitled'"}
                  </div>
                  {file.type === 'file' && file.size && (
                    <div className='text-[10px] text-muted-foreground truncate'>{formatFileSize(file.size)}</div>
                  )}
                </>
              )}
            </div>
          </div>
        </div>

        {/* Selection indicator */}
        {isSelected && (
          <div className='absolute top-2 right-2'>
            <div className='bg-primary rounded-full p-1 shadow-sm'>
              <Check className='h-3 w-3 text-primary-foreground' />
            </div>
          </div>
        )}

        {/* Actions (visible on hover) */}
        <div className='absolute top-2 left-2 opacity-0 group-hover:opacity-100 transition-opacity'>
          <FileActions
            file={file}
            viewMode='grid'
            onDownload={onDownloadFile}
            onPreview={onPreviewFile}
            onEdit={onEditFile}
            onDelete={onDeleteFile}
          />
        </div>
      </CardContent>
    </Card>
  );
}
