'use client';

import { MoreHorizontal, Download, Trash2, Edit, Eye } from 'lucide-react';
import { Button } from './components/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from './components/ui/dropdown-menu';
import { FileItem } from './lib/types';

interface FileActionsProps {
  file: FileItem;
  viewMode: 'list' | 'grid';
  onDownload: (file: FileItem) => void;
  onPreview: (file: FileItem) => void;
  onEdit: (file: FileItem) => void;
  onDelete: (file: FileItem) => void;
}

export function FileActions({ file, viewMode, onDownload, onPreview, onEdit, onDelete }: FileActionsProps) {
  const iconSize = viewMode === 'list' ? 'h-4 w-4' : 'h-3 w-3';
  const buttonClass = viewMode === 'list' ? 'h-6 w-6 p-0' : 'h-6 w-6 p-0 bg-white/80 hover:bg-white';

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant='ghost' size='icon' className={buttonClass}>
          <MoreHorizontal className={iconSize} />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align={viewMode === 'list' ? 'end' : 'start'}>
        <DropdownMenuItem
          onClick={(e) => {
            e.stopPropagation();
            onPreview(file);
          }}
        >
          <Eye className={`${iconSize} mr-2`} />
          Preview
        </DropdownMenuItem>
        <DropdownMenuItem
          onClick={(e) => {
            e.stopPropagation();
            onDownload(file);
          }}
        >
          <Download className={`${iconSize} mr-2`} />
          Download
        </DropdownMenuItem>
        <DropdownMenuItem
          onClick={(e) => {
            e.stopPropagation();
            onEdit(file);
          }}
        >
          <Edit className={`${iconSize} mr-2`} />
          Rename
        </DropdownMenuItem>
        <DropdownMenuItem
          className='text-red-600'
          onClick={(e) => {
            e.stopPropagation();
            onDelete(file);
          }}
        >
          <Trash2 className={`${iconSize} mr-2`} />
          Delete
        </DropdownMenuItem>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}
