'use client';

import React, { createContext, useContext } from 'react';
import { type HttpClient } from '@softimist/api';

/**
 * FileManager configuration interface
 */
export interface FileManagerConfig {
  assetBaseUrl: string;
  uploadEndpoint: string;
}

/**
 * App-specific components that need to be provided by the consuming app
 */
export interface FileManagerComponents {
  Image?: React.ComponentType<{ src: string; alt: string; width?: number; height?: number; className?: string }>;
  VideoPlayer?: React.ComponentType<{ id: string; src: string; title: string }>;
}

interface FileManagerContextValue {
  apiClient: HttpClient;
  config: FileManagerConfig;
  components?: FileManagerComponents;
}

const FileManagerContext = createContext<FileManagerContextValue | null>(null);

export interface FileManagerProviderProps {
  apiClient: HttpClient;
  config: FileManagerConfig;
  components?: FileManagerComponents;
  children: React.ReactNode;
}

export function FileManagerProvider({
  apiClient,
  config,
  components,
  children,
}: FileManagerProviderProps) {
  const value: FileManagerContextValue = {
    apiClient,
    config,
    components,
  };

  return <FileManagerContext.Provider value={value}>{children}</FileManagerContext.Provider>;
}

export function useFileManagerContext(): FileManagerContextValue {
  const context = useContext(FileManagerContext);
  if (!context) {
    throw new Error('useFileManagerContext must be used within FileManagerProvider');
  }
  return context;
}
