'use client';

import {
  Pagination,
  PaginationContent,
  PaginationEllipsis,
  PaginationItem,
  PaginationLink,
  PaginationNext,
  PaginationPrevious,
} from './components/ui/pagination';
import type { UsePaginatedApiReturn } from '@softimist/api';
import { FileItem } from './lib/types';

interface FileManagerPaginationProps {
  res: UsePaginatedApiReturn<FileItem>;
}

/**
 * Generates an array of page numbers to display with ellipsis logic
 * Shows: first page, pages around current, and last page
 */
function generatePageNumbers(currentPage: number, totalPages: number): (number | 'ellipsis')[] {
  const pages: (number | 'ellipsis')[] = [];
  const delta = 2; // Number of pages to show on each side of current page

  // If total pages is small, show all pages
  if (totalPages <= 7) {
    for (let i = 1; i <= totalPages; i++) {
      pages.push(i);
    }
    return pages;
  }

  // Always show first page
  pages.push(1);

  // Calculate the range around current page
  const start = Math.max(2, currentPage - delta);
  const end = Math.min(totalPages - 1, currentPage + delta);

  // Add ellipsis after first page if there's a gap
  if (start > 2) {
    pages.push('ellipsis');
  }

  // Add pages around current page (excluding first and last which are handled separately)
  for (let i = start; i <= end; i++) {
    if (i !== 1 && i !== totalPages) {
      pages.push(i);
    }
  }

  // Add ellipsis before last page if there's a gap
  if (end < totalPages - 1) {
    pages.push('ellipsis');
  }

  // Always show last page (if it's not already included)
  if (totalPages > 1 && !pages.some((p) => p === totalPages)) {
    pages.push(totalPages);
  }

  return pages;
}

export function FileManagerPagination({ res }: FileManagerPaginationProps) {
  if (!res.pagination || res.pagination.total_pages <= 1) {
    return null;
  }

  const totalPages = res.pagination.total_pages;
  const currentPage = res.page;
  const pageNumbers = generatePageNumbers(currentPage, totalPages);

  return (
    <div className='flex justify-center mt-4'>
      <Pagination>
        <PaginationContent>
          <PaginationItem>
            <PaginationPrevious
              href="#"
              onClick={(e) => {
                e.preventDefault();
                res.setPage(Math.max(1, currentPage - 1));
              }}
              className={currentPage === 1 ? 'pointer-events-none opacity-50' : 'cursor-pointer'}
            />
          </PaginationItem>

          {pageNumbers.map((page, index) => {
            if (page === 'ellipsis') {
              return (
                <PaginationItem key={`ellipsis-${index}`}>
                  <PaginationEllipsis />
                </PaginationItem>
              );
            }

            return (
              <PaginationItem key={page}>
                <PaginationLink
                  href="#"
                  onClick={(e) => {
                    e.preventDefault();
                    res.setPage(page);
                  }}
                  isActive={currentPage === page}
                  className='cursor-pointer px-2'
                  size={page > 9999 ? 'default' : 'icon'}
                >
                  {page}
                </PaginationLink>
              </PaginationItem>
            );
          })}

          <PaginationItem>
            <PaginationNext
              href="#"
              onClick={(e) => {
                e.preventDefault();
                res.setPage(Math.min(totalPages, currentPage + 1));
              }}
              className={currentPage === totalPages ? 'pointer-events-none opacity-50' : 'cursor-pointer'}
            />
          </PaginationItem>
        </PaginationContent>
      </Pagination>
    </div>
  );
}
