'use client';

import { Button } from '../components/ui/button';
import { Progress } from '../components/ui/progress';
import { Play, Pause, Square, Upload, RotateCcw, Check } from 'lucide-react';
import { useUploaderState } from './state';

type Props = {
  onClose: () => void;
};

export function UploadControls({ onClose }: Props) {
  const { state, handleUpload, handlePauseResume, handleCancel } = useUploaderState();

  if (!state.isUploading && !Object.keys(state.files).length) {
    return <p className='text-muted-foreground text-center'>Please select files to upload.</p>;
  }

  if (!state.isUploading) {
    return (
      <Button onClick={handleUpload} className='flex items-center gap-2'>
        <Upload className='h-4 w-4' />
        Start Upload
      </Button>
    );
  }

  return (
    <>
      <div className='flex items-center gap-4'>
        <div className='flex-1 min-w-32 border rounded-md p-2'>
          <Progress value={state.progress} className='h-2' />
          <p className='text-xs text-muted-foreground mt-1'>{Math.round(state.progress)}% complete</p>
        </div>
        <div className='flex items-center gap-2'>
          {state.canPause && (
            <Button
              variant='outline'
              size='sm'
              onClick={handlePauseResume}
              className='flex items-center gap-1 bg-transparent'
            >
              {state.isPaused ? (
                <>
                  <Play className='h-3 w-3' />
                  Resume
                </>
              ) : (
                <>
                  <Pause className='h-3 w-3' />
                  Pause
                </>
              )}
            </Button>
          )}

          {state.error && (
            <Button variant='outline' size='sm' onClick={handleUpload}>
              <RotateCcw className='h-3 w-3' />
              Retry
            </Button>
          )}

          {state.canCancel && (
            <Button variant='destructive' size='sm' onClick={handleCancel}>
              <Square className='h-3 w-3' />
              Cancel
            </Button>
          )}
        </div>
      </div>
      {state.error && <p className='text-xs text-destructive mt-1'>{state.error}</p>}
      {state.progress === 100 && !state.error && (
        <Button onClick={onClose}>
          <Check className='size-4' />
          Done
        </Button>
      )}
    </>
  );
}
