import React from 'react';
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from './components/ui/breadcrumb';
import { FileItem } from './lib/types';

type Props = {
  pwd: FileItem[];
  setPwd: (pwd: FileItem[]) => void;
};

export function FileManagerBreadcrumb({ pwd, setPwd }: Props) {
  const navigateToIndex = (index: number) => {
    setPwd(pwd.slice(0, index + 1));
  };

  return (
    <Breadcrumb className='py-2'>
      <BreadcrumbList>
        {pwd.map((item, index) => (
          <React.Fragment key={item.id}>
            <BreadcrumbItem>
              {index === pwd.length - 1 ? (
                <BreadcrumbPage>{item.name || 'Untitled'}</BreadcrumbPage>
              ) : (
                <BreadcrumbLink onClick={() => navigateToIndex(index)}>{item.name || 'Untitled'}</BreadcrumbLink>
              )}
            </BreadcrumbItem>
            {index < pwd.length - 1 && <BreadcrumbSeparator />}
          </React.Fragment>
        ))}
      </BreadcrumbList>
    </Breadcrumb>
  );
}
